from pathlib import Path
p=Path("tests/local/number-methods.js")
s=p.read_text()
marker='console.log("number-methods PASS " + passed + "/" + passed);\n'
assert s.count(marker)==1
s=s.replace(marker, '\nok("toString shortest decimal", (1000000000000000128).toString() === "1000000000000000100");\nok("toString lower fixed threshold", (0.000001).toString() === "0.000001");\nok("toString lower exponential threshold", (0.0000001).toString() === "1e-7");\nok("toString minimum subnormal", Number.MIN_VALUE.toString() === "5e-324");\nok("toString maximum finite", Number.MAX_VALUE.toString() === "1.7976931348623157e+308");\nok("toString radix exact integer", (2 ** 53).toString(2) === "100000000000000000000000000000000000000000000000000000");\nok("toString radix negative", (-255).toString(16) === "-ff");\n\nok("toFixed exact half up", (1.25).toFixed(1) === "1.3");\nok("toFixed second exact half up", (2.25).toFixed(1) === "2.3");\nok("toFixed binary approximation", (1.005).toFixed(2) === "1.00");\nok("toFixed fractional tie", (0.125).toFixed(2) === "0.13");\nok("toFixed negative tie", (-1.25).toFixed(1) === "-1.3");\nok("toFixed large fallback", (1e21).toFixed(2) === "1e+21");\n\nok("toExponential exact tie", (25).toExponential(0) === "3e+1");\nok("toExponential shortest", (1.234567890123).toExponential() === "1.234567890123e+0");\nok("toPrecision zero", (0).toPrecision(3) === "0.00");\nok("toPrecision negative zero", (-0).toPrecision(3) === "0.00");\nok("toPrecision fixed", (123.456).toPrecision(5) === "123.46");\nok("toPrecision carry", (9.99).toPrecision(2) === "10");\nok("toPrecision exponential carry", (999).toPrecision(2) === "1.0e+3");\n\nconst firstLocale = (1234.5).toLocaleString();\nconst secondLocale = (1234.5).toLocaleString();\nok("toLocaleString default cache result", firstLocale === secondLocale);\nlet groupingReads = 0;\nconst localeOptions = {\n\tget useGrouping() {\n\t\tgroupingReads++;\n\t\treturn false;\n\t},\n};\n(1234.5).toLocaleString(undefined, localeOptions);\n(1234.5).toLocaleString(undefined, localeOptions);\nok("toLocaleString custom options remain observable", groupingReads === 2);\n'+'\n'+marker)
p.write_text(s)
